/**
 * Model User
 * 
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model RolePermission
 * What one role may do. A role with no row runs on the shipped defaults.
 */
export type RolePermission = $Result.DefaultSelection<Prisma.$RolePermissionPayload>
/**
 * Model AuditLog
 * 
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model Counter
 * Named running numbers (UHID, invoice, sample ...). Kept as a table rather
 * than one Postgres SEQUENCE each so the existing getNext*() helpers map over
 * directly: an upsert with `seq: { increment: 1 }` is atomic.
 */
export type Counter = $Result.DefaultSelection<Prisma.$CounterPayload>
/**
 * Model Department
 * 
 */
export type Department = $Result.DefaultSelection<Prisma.$DepartmentPayload>
/**
 * Model Doctor
 * 
 */
export type Doctor = $Result.DefaultSelection<Prisma.$DoctorPayload>
/**
 * Model Organization
 * 
 */
export type Organization = $Result.DefaultSelection<Prisma.$OrganizationPayload>
/**
 * Model LabTest
 * 
 */
export type LabTest = $Result.DefaultSelection<Prisma.$LabTestPayload>
/**
 * Model TestParameter
 * One row per parameter band - the same parameter repeats for each sex and
 * age window it has a range for, and the sheet picks the row that fits.
 */
export type TestParameter = $Result.DefaultSelection<Prisma.$TestParameterPayload>
/**
 * Model TestAttachment
 * A reference file kept with a test. Its own table so listing the catalogue
 * never drags the bytes along - `data` should be left out via Prisma `omit`.
 */
export type TestAttachment = $Result.DefaultSelection<Prisma.$TestAttachmentPayload>
/**
 * Model TestPackage
 * 
 */
export type TestPackage = $Result.DefaultSelection<Prisma.$TestPackagePayload>
/**
 * Model TestPackageItem
 * Package ↔ test. An explicit join so the order the tests were listed in
 * survives - Mongo kept it as array order.
 */
export type TestPackageItem = $Result.DefaultSelection<Prisma.$TestPackageItemPayload>
/**
 * Model RateHistory
 * 
 */
export type RateHistory = $Result.DefaultSelection<Prisma.$RateHistoryPayload>
/**
 * Model RefundPolicy
 * The centre's single return policy. `singleton` is fixed so "create it if
 * missing" stays an upsert.
 */
export type RefundPolicy = $Result.DefaultSelection<Prisma.$RefundPolicyPayload>
/**
 * Model Patient
 * 
 */
export type Patient = $Result.DefaultSelection<Prisma.$PatientPayload>
/**
 * Model Appointment
 * 
 */
export type Appointment = $Result.DefaultSelection<Prisma.$AppointmentPayload>
/**
 * Model AppointmentTest
 * Appointment ↔ test, in the order the tests were booked.
 */
export type AppointmentTest = $Result.DefaultSelection<Prisma.$AppointmentTestPayload>
/**
 * Model Invoice
 * 
 */
export type Invoice = $Result.DefaultSelection<Prisma.$InvoicePayload>
/**
 * Model InvoiceItem
 * One line on a bill. Frozen copies of the test's name, code and department
 * so the bill still reads correctly after the master changes.
 */
export type InvoiceItem = $Result.DefaultSelection<Prisma.$InvoiceItemPayload>
/**
 * Model InvoicePaymentSplit
 * What came in by each method on one bill. The Payment rows stay the ledger;
 * this is the per-method running total the directory reads.
 */
export type InvoicePaymentSplit = $Result.DefaultSelection<Prisma.$InvoicePaymentSplitPayload>
/**
 * Model InvoiceRevision
 * 
 */
export type InvoiceRevision = $Result.DefaultSelection<Prisma.$InvoiceRevisionPayload>
/**
 * Model Payment
 * Money the centre has. Written only once a collection actually succeeds.
 */
export type Payment = $Result.DefaultSelection<Prisma.$PaymentPayload>
/**
 * Model PaymentTransaction
 * One attempt at collecting through a machine (UPI / card). Separate from
 * Payment so a declined card never lands in the day's takings.
 */
export type PaymentTransaction = $Result.DefaultSelection<Prisma.$PaymentTransactionPayload>
/**
 * Model Refund
 * 
 */
export type Refund = $Result.DefaultSelection<Prisma.$RefundPayload>
/**
 * Model Expense
 * The outgoing-cash ledger (payouts): ambulance, courier, doctor cut, supplier.
 */
export type Expense = $Result.DefaultSelection<Prisma.$ExpensePayload>
/**
 * Model Sample
 * 
 */
export type Sample = $Result.DefaultSelection<Prisma.$SamplePayload>
/**
 * Model SampleStatusHistory
 * 
 */
export type SampleStatusHistory = $Result.DefaultSelection<Prisma.$SampleStatusHistoryPayload>
/**
 * Model Result
 * 
 */
export type Result = $Result.DefaultSelection<Prisma.$ResultPayload>
/**
 * Model ResultParameter
 * One line of a result sheet. Limits are copied off the test master so a
 * re-flag on save uses the ranges the sheet was built with.
 */
export type ResultParameter = $Result.DefaultSelection<Prisma.$ResultParameterPayload>
/**
 * Model ResultVersion
 * A snapshot of the sheet at each status change. Only ever read back whole,
 * so the parameter lines are kept as JSONB rather than another child table.
 */
export type ResultVersion = $Result.DefaultSelection<Prisma.$ResultVersionPayload>
/**
 * Model SavedReport
 * A report PDF exactly as it was handed over. `data` should be left out of
 * list reads via Prisma `omit`.
 */
export type SavedReport = $Result.DefaultSelection<Prisma.$SavedReportPayload>

